159	<script>
160	  // AI 提问页（v1.16.90）：问题文本 → AssistantEngine.chat（真链路 ai_chat / 模拟链路本地检索）
161	  // → global.aiResult → replace 到回答页 /pages/ai/ai-answer
162	  import router from '@system.router'
163	  import device from '@system.device'
164	  import { getAssistant } from '../../../SearchEngine/AssistantEngine.js'
165	
166	  export default {
167	    private: {
168	      // 状态机：input（输入）→ preparing（准备回答）→ replace 回答页；error（失败可重试）
169	      status: 'input',
170	      question: '',
171	      showKeyboard: false,
172	      // 屏幕形态（键盘组件所需，device.getInfo 异步回填）
173	      screentype: 'rect',
174	      // 转圈字符帧（setInterval 500ms 轮换；不用 CSS animation——运行时支持不可靠）
175	      spinnerText: '● ○ ○',
176	      spinnerTimer: null,
177	      // 语音输入态
178	      voiceBusy: false,
179	      micText: '语音输入',
180	      // 错误提示（可重试）
181	      errMsg: '',
182	      isDestroyed: false
183	    },
184	
185	    computed: {
186	      // 键盘打开时追加光标（与输入组件内部光标一致，避免特殊字符缺字）
187	      displayQuestion() {
188	        return this.question + (this.showKeyboard ? '_' : '')
189	      },
190	      // 提问按钮态类：有词可点（蓝）/ 无词禁用（灰）——完整类名 JS 预拼，模板纯变量插值
191	      sendBtnClass() {
192	        var q = (this.question || '').trim()
193	        return q ? 'send-btn send-btn-on' : 'send-btn send-btn-off'
194	      },
195	      // 麦克风按钮态类：聆听中蓝底
196	      micBtnClass() {
197	        return this.voiceBusy ? 'mic-btn mic-btn-busy' : 'mic-btn'
198	      }
199	    },
200	
201	    onInit() {
202	      // 屏幕形态（键盘组件所需；device.getInfo 异步回填，与 dataset.ux 同款）
203	      var self = this
204	      device.getInfo({
205	        success: function(data) {
206	          var shape = data.screenShape
207	          self.screentype = shape === 'circle' ? 'circle' : (shape === 'pill-shaped' ? 'pill-shaped' : 'rect')
208	        },
209	        fail: function() {}
210	      })
211	    },
212	
213	    onDestroy() {
214	      this.isDestroyed = true
215	      this.stopSpinner()
216	      if (this._voiceTimer) { clearTimeout(this._voiceTimer); this._voiceTimer = null }
217	      // 离页作废在途请求（模拟定时器 + 真链路超时定时器 + 回调）
218	      getAssistant().cancel()
219	    },
220	
221	    // ===== 键盘输入 =====
222	    // 点文本框：开/收键盘；开键盘延迟 60ms 让 if 组件先 mount（dataset.ux v1.16.81 同款）
223	    toggleKeyboard() {
224	      if (this.status !== 'input') return
225	      if (this.showKeyboard) { this.showKeyboard = false; return }
226	      var self = this
227	      setTimeout(function() {
228	        if (!self.isDestroyed && self.status === 'input') self.showKeyboard = true
229	      }, 60)
230	    },
231	
232	    // @complete：键盘逐字符追加进问题文本
233	    onInput(evt) {
234	      var content = evt.detail.content
235	      if (content === undefined || content === null) return
236	      this.question += content
237	    },
238	
239	    // @delete：键盘内部缓冲已空时删问题末字符
240	    onDelete() {
241	      this.question = this.question.slice(0, -1)
242	    },
243	
244	    // ===== 语音输入：识别文本追加进文本框（模拟链路约 1.5s 返回） =====
245	    startVoice() {
246	      if (this.status !== 'input' || this.voiceBusy) return
247	      this.voiceBusy = true
248	      this.micText = '聆听中…'
249	      var self = this
250	      // 12s 超时兜底：真链路手机不回包时不无限卡在聆听态
251	      this._voiceTimer = setTimeout(function() {
252	        if (self.isDestroyed || !self.voiceBusy) return
253	        self.voiceBusy = false
254	        self.micText = '语音输入'
255	        getAssistant().cancel()
256	      }, 12000)
257	      getAssistant().recognize(function(r) {
258	        if (self._voiceTimer) { clearTimeout(self._voiceTimer); self._voiceTimer = null }
259	        if (self.isDestroyed) return
260	        self.voiceBusy = false
261	        self.micText = '语音输入'
262	        if (self.status !== 'input') return
263	        if (r && r.ok && r.text) {
264	          self.question += r.text
265	        }
266	      })
267	    },
268	
269	    // ===== 提问：进入准备态 → chat() → global.aiResult → replace 回答页 =====
270	    submit() {
271	      if (this.status === 'preparing') return
272	      var q = (this.question || '').trim()
273	      if (!q) return   // 空问题不可提问（按钮同为禁用态）
274	      this.showKeyboard = false
275	      this.status = 'preparing'
276	      this.errMsg = ''
277	      this.startSpinner()
278	      var self = this
279	      var searchFn = function(kw) {
280	        // 复用既有搜索通道（global.searchHistory → searchAllAsync → 各集引擎），与首页 runAiSearch 相同
281	        return Promise.resolve().then(function() {
282	          return global.searchHistory(kw, { page: 1, pageSize: 5, category: 'all', region: 'all' })
283	        })
284	      }
285	      getAssistant().chat(q, searchFn, function(r) {
286	        // 已取消（滑动回输入态）/已离页：过期回调直接丢弃
287	        if (self.isDestroyed || self.status !== 'preparing') return
288	        self.stopSpinner()
289	        if (r && r.ok) {
290	          // 结果经 global 桥接传给回答页（模块实例按页面作用域隔离，不能靠页面间 import 共享）
291	          global.aiResult = { question: q, answer: r.answer, sources: r.sources || [] }
292	          // replace：从回答页返回应回首页，不应回到准备态
293	          router.replace({ uri: '/pages/ai/ai-answer' })
294	        } else {
295	          self.status = 'error'
296	          self.errMsg = (r && r.reason === 'empty')
297	            ? '没能理解这个问题，换个说法试试'
298	            : 'AI 暂时不可用，请稍后再试'
299	        }
300	      })
301	    },
302	
303	    // ===== 转圈：500ms 轮换字符帧（onDestroy/stopSpinner 清定时器） =====
304	    startSpinner() {
305	      var frames = ['● ○ ○', '○ ● ○', '○ ○ ●']
306	      var idx = 0
307	      var self = this
308	      this.stopSpinner()
309	      this.spinnerText = frames[0]
310	      this.spinnerTimer = setInterval(function() {
311	        idx = (idx + 1) % frames.length
312	        self.spinnerText = frames[idx]
313	      }, 500)
314	    },
315	
316	    stopSpinner() {
317	      if (this.spinnerTimer) {
318	        clearInterval(this.spinnerTimer)
319	        this.spinnerTimer = null
320	      }
321	    },
322	
323	    backToInput() {
324	      this.status = 'input'
325	      this.errMsg = ''
326	    },
327	
328	    // ===== 滑动：准备态=取消；错误态=回输入态；键盘开着先收；否则左右滑返回 =====
329	    onSwipe(eve) {
330	      if (this.status === 'preparing') {
331	        this.cancelPrepare()
332	        return
333	      }
334	      if (this.status === 'error') {
335	        this.backToInput()
336	        return
337	      }
338	      if (this.showKeyboard) {
339	        this.showKeyboard = false
340	        return
341	      }
342	      if (eve.direction === 'left' || eve.direction === 'right') {
343	        router.back()
344	      }
345	    },
346	
347	    // 取消准备：清转圈 + 作废在途请求（cancel 内含 cancelSim 清模拟定时器、清 chat 超时定时器与回调）
348	    cancelPrepare() {
349	      this.stopSpinner()
350	      getAssistant().cancel()
351	      this.status = 'input'
352	    }
353	  }
354	</script>
