30	var SIM_LATENCY = 1500          // 模拟识别延迟（ms）：贴近真实语音识别耗时
31	var SIM_AI_LATENCY = 900        // 模拟 AI 思考延迟（ms）
32	var SIM_CHAT_LATENCY = 2500     // 模拟 AI 问答延迟（ms）：用户指定的小爱式"准备回答"节奏
33	var CHAT_TIMEOUT = 12000        // 真链路 ai_chat 应答超时（ms）：超时降级本地模拟
