51	  this.conn = null
52	  this._voiceCb = null
53	  this._aiCb = null
54	  this._simTimer = null
55	  this._probeDone = false
56	  // ai_chat（v1.16.90）：_chatSeq=自增序号（即协议 qid）；_chatDone=本次请求已消费
57	  //（超时降级后迟到回包、旧 qid 回包都靠它+序号比对拦截，防双重回调/旧答案污染）
58	  this._chatCb = null
