64	// 探测通道：真链路优先（interconnect 就绪），否则模拟。结果缓存（连接状态变化时 reprobe）。
65	Assistant.prototype.probe = function (onReady) {
66	  var self = this
67	  if (this._probeDone && this.mode) { onReady(this.mode); return }
68	  try {
69	    var interconnect = require('@system.interconnect')
70	    var conn = interconnect.instance()
71	    conn.getReadyState({
72	      success: function (data) {
73	        if (data && data.status === 1) {
74	          self.mode = MODE.REAL
75	          self.conn = conn
76	          self._bindReal(conn)
77	        } else {
78	          self.mode = MODE.SIM
79	        }
80	        self._probeDone = true
81	        onReady(self.mode)
82	      },
83	      fail: function () {
84	        self.mode = MODE.SIM
85	        self._probeDone = true
86	        onReady(self.mode)
87	      }
88	    })
89	  } catch (e) {
90	    // 模拟器上 interconnect 通常不可 require 或无对端 → 模拟链路
91	    this.mode = MODE.SIM
92	    this._probeDone = true
93	    onReady(this.mode)
94	  }
95	}
