97	// 绑定真链路消息（手机 App 的应答）
98	// ⚠️ 包装链（审查修复）：BtTransfer（蓝牙资料接收）也在这条通道设 conn.onmessage，
99	// 直接赋值会互相覆盖。保留原 handler，非本模块消息转发过去，两模块都能收到。
100	Assistant.prototype._bindReal = function (conn) {
101	  var self = this
102	  var prevHandler = conn.onmessage
103	  conn.onmessage = function (data) {
104	    var handled = false
105	    if (data && data.data) {
106	      var msg = null
107	      try { msg = JSON.parse(data.data) } catch (e) { msg = null }
108	      if (msg && msg.type === 'voice_result' && self._voiceCb) {
109	        self._voiceCb({ ok: true, text: msg.text || '', mode: MODE.REAL })
110	        handled = true
111	      } else if (msg && msg.type === 'ai_result' && self._aiCb) {
112	        self._aiCb({ ok: true, answer: msg.answer || '', results: msg.results || [], mode: MODE.REAL })
113	        handled = true
114	      } else if (msg && msg.type === 'ai_chat_result') {
115	        // ai_chat 应答（v1.16.90）：qid 必须等于当前挂起序号（自增匹配），且本次请求
116	        // 尚未消费（超时降级后迟到回包在此拦截）——其余一律丢弃，防旧答案污染新问题。
117	        // 无论是否命中都按已消费处理（本协议消息不转发 prevHandler，BtTransfer 无此类型）。
118	        if (self._chatCb && msg.qid === self._chatSeq && !self._chatDone) {
119	          self._chatDone = true
120	          if (self._chatTimer) { clearTimeout(self._chatTimer); self._chatTimer = null }
121	          self._chatCb(msg.ok
122	            ? { ok: true, answer: msg.answer || '', sources: msg.sources || [], mode: MODE.REAL }
123	            : { ok: false, reason: 'remote_error' })
124	        }
125	        handled = true
126	      }
127	    }
128	    if (!handled && typeof prevHandler === 'function') {
129	      try { prevHandler(data) } catch (e) {}
130	    }
131	  }
132	}
