170	  var self = this
171	  this._aiCb = cb
172	  this.cancelSim()
173	  this.probe(function (mode) {
174	    if (mode === MODE.REAL) {
175	      try {
176	        self.conn.send({ data: JSON.stringify({ type: 'ai_search', q: question }) })
177	      } catch (e) {
