186	Assistant.prototype._simAI = function (question, searchFn, cb) {
187	  var self = this
188	  var keyword = this._understand(question)
189	  if (!keyword) { cb({ ok: false, reason: 'empty' }); return }
190	  var t0 = Date.now()
191	  searchFn(keyword).then(function (result) {
192	    var items = (result && result.results) || []
193	    var total = (result && result.total) || 0
194	    // 摘要生成：由检索结果真实拼出（与 _simChat 共用 _composeAnswer，不复制粘贴）
