214	  return lines.length
215	    ? ('关于「' + keyword + '」，共找到 ' + total + ' 条资料：' + lines.join('；') + '。')
216	    : ('本地资料中未找到与「' + keyword + '」直接相关的内容，换个说法试试？')
217	}
